// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let slider;
let phase = 1;
let zoff = 1;
let angle =0;
var seed = Math.random() * 1000;
let colors1 = "66139640-e66a1620-0de935bf-d12f6433-fade5b80".split("-").map((a) => "#" + a);
let colorbg = "fbf8ef".split("-").map((a) => "#" + a);
let colorbg2 = "fbf8ef03".split("-").map((a) => "#" + a);

function setup() {
	randomSeed(seed);
  createCanvas(windowWidth, windowHeight);
  // pixelDensity(5);
  background(colorbg);
  slider = random(1.5, 2.5);
	// let filter = new makeFilter();
}

function draw() {
	randomSeed(seed);
  background(colorbg);
  translate(width / 2, height / 2);
  let gap = 0.012;

  for (var i = 0; i < 200; i++) {
    let noiseMax = slider;
    noStroke();

    beginShape();
    for (var a = 0; a < random(0, PI); a += 0.04) {
      fill(random(colors1));
      rotate(random(HALF_PI)+angle);
      let xoff = map(cos(a + phase), -1, 1, 0, noiseMax);
      let yoff = map(sin(a + phase / 2), -1, 1, 0, noiseMax);
      let r = map(noise(xoff, yoff, zoff), 0, 1, 100, 150) * i * gap;
      let x = r * cos(a);
      let y = r * sin(a);
      vertex(x, y);
    }
    endShape();

    beginShape();
    for (var b = 0; b < random(0, PI); b += 0.01) {
      fill(random(colors1));
      rotate(random(HALF_PI)+angle);
      var xoff = map(cos(b + phase), -1, 1, 0, noiseMax);
      var yoff = map(sin(b + phase / 2), -1, 1, 0, noiseMax);
      var r = map(noise(xoff, yoff, zoff), 0, 1, 100, 150) * i * gap;
      var x = r * cos(b);
      var y = r * sin(b);
      vertex(x, y);
    }
    endShape();

    beginShape();
    for (var c = 0; c < random(0, PI); c += 0.02) {
      fill(random(colors1));
      rotate(random(HALF_PI)+angle);
      var xoff = map(cos(c + phase), -1, 1, 0, noiseMax);
      var yoff = map(sin(c + phase / 2), -1, 1, 0, noiseMax);
      var r = map(noise(xoff, yoff, zoff), 0, 1, 100, 150) * i * gap;
      var x = r * cos(c);
      var y = r * sin(c);
      vertex(x, y);
    }
    endShape();
     slider += 0.001;
  }

  phase += random(0.005);
  zoff += random(0.005);
	// image(overAllTexture, 0, 0)
	angle +=PI/360/1000 ;
}

function makeFilter() {
	randomSeed(seed);
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 10);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(48, 53, 70, noise(i / 3, j / 3, (i * j) / 50) * random(10))
			);
		}
	}
	overAllTexture.updatePixels();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("NoiseWaves_01", "png");
	}
}

